def calc(expr):
    match expr.split():
        case [a, '+', b]:
            return int(a) + int(b)
        case [a, '-', b]:
            return int(a) - int(b)
        case [a, '*', b]:
            return int(a) * int(b)
        case _:
            return None

print(calc('3 + 4'))
print(calc('9 * 9'))
